```javascript
function resetGame(seed) {
  rng = mulberry32(seed);
  score = 0;
  lives = 3;
  gameState = 'PLAYING';
  moveCooldown = 0;

  player = {
    x: 200,
    row: 5,
    oldRow: 5,
    jumpFrames: 0,
    size: 24
  };

  riverRows = [];
  let dirs = [-1, 1, -1, 1]; // Alternating river directions

  for (let r = 1; r <= 4; r++) {
    let speed = (1.5 + rng() * 1.5) * dirs[r - 1];
    let numLogs = 4;
    let spacing = 400 / numLogs;
    let rowOffset = rng() * 400;
    let logs = [];

    for (let i = 0; i < numLogs; i++) {
      logs.push({
        x: (i * spacing + rowOffset) % 400,
        w: 50 + rng() * 30, // Random log width between 50 and 80
        visited: false
      });
    }

    riverRows.push({
      row: r,
      y: r * 60,
      speed: speed,
      logs: logs
    });
  }

  temple = {
    x: 170,
    w: 60,
    blocks: 0,
    target: 12, // Needs 12 unique log visits to open
    open: false
  };

  // Generate deterministic jungle decorations
  decorations = [];

  // Hanging vines at the top
  for (let i = 0; i < 12; i++) {
    decorations.push({
      type: 'vine',
      x: rng() * 400,
      y: 10 + rng() * 30, // length
      scale: 0.5 + rng() * 1.0
    });
  }

  // Top bank trees & bushes
  for (let i = 0; i < 10; i++) {
    decorations.push({
      type: rng() > 0.5 ? 'tree' : 'bush',
      x: rng() * 400,
      y: 10 + rng() * 35,
      scale: 0.7 + rng() * 0.6
    });
  }

  // Bottom bank trees & bushes
  for (let i = 0; i < 18; i++) {
    let side = rng();
    let xpos;
    if (side < 0.45) {
      xpos = rng() * 120;
    } else if (side < 0.9) {
      xpos = 280 + rng() * 120;
    } else {
      xpos = 120 + rng() * 160;
    }

    // Push away from the center start position to keep path clear
    if (xpos > 160 && xpos < 240) {
      xpos = xpos < 200 ? 160 : 240;
    }

    decorations.push({
      type: rng() > 0.4 ? 'tree' : 'bush',
      x: xpos,
      y: 310 + rng() * 80,
      scale: 0.7 + rng() * 0.7
    });
  }
}
```

